264: func leadJitter(lead time.Duration, source io.Reader) time.Duration {
265: 	span := lead / 10 / time.Millisecond
266: 	if span <= 0 {
267: 		return 0
268: 	}
269: 	if source == nil {
270: 		source = rand.Reader
271: 	}
272: 	n, err := rand.Int(source, big.NewInt(int64(2*span+1)))
273: 	if err != nil {
274: 		return 0
275: 	}
276: 	return (time.Duration(n.Int64()) - span) * time.Millisecond
277: }

