286: func (e *Engine) renewalJitter(window time.Duration) time.Duration {
287: 	if !e.leaseJitter.valid || e.leaseJitter.id != e.lease.LeaseId || !e.leaseJitter.issued.Equal(e.lease.IssuedAt) {
288: 		e.leaseJitter = renewalJitter{valid: true, id: e.lease.LeaseId, issued: e.lease.IssuedAt,
